import React, { useState, useEffect } from 'react';
// CORRECTED IMPORTS: Components are typically in the '../components' folder,
// so we change './Component' to '../components/Component'.
import UserManagement from '../components/UserManagement'; 
import ItemReview from '../components/ItemReview';
import Analytics from '../components/Analytics';
import AuditLogs from '../components/AuditLogs';
// Assuming useAuth is imported from context or defined locally
// FIX: Changed 'AuthContext' to lowercase 'authcontext' to match the file on disk (authcontext.js)
import { useAuth } from '../context/authcontext'; 

// --- Mock useAuth for demonstration if AuthContext is not fully defined ---
/*
const useAuth = () => ({
  user: {
    name: 'Admin User',
    role: 'super_admin' // Role is key for RBAC
  },
  // Function to check if the user has permission for a specific feature
  hasPermission: (requiredRoles) => {
    const userRole = 'super_admin'; // Replace with actual user role
    return requiredRoles.includes(userRole);
  }
});
*/
// --------------------------------------------------

const AdminDashboard = () => {
  const { user, hasPermission } = useAuth();
  const [activeTab, setActiveTab] = useState('user-management');

  // Define tabs and their required roles for access
  const dashboardTabs = [
    { id: 'user-management', name: 'User Management', roles: ['admin', 'super_admin'] },
    { id: 'item-review', name: 'Item Review & Claims', roles: ['admin', 'super_admin', 'moderator'] },
    { id: 'analytics', name: 'System Analytics', roles: ['admin', 'super_admin', 'analyst'] },
    { id: 'audit-logs', name: 'Audit Logs', roles: ['admin', 'super_admin'] },
  ];

  const renderContent = () => {
    // Get the role of the logged-in user for passing to children
    const userRole = user?.role || 'guest';

    switch (activeTab) {
      case 'user-management':
        return <UserManagement userRole={userRole} />;
      case 'item-review':
        // Crucially passing userRole here to hide the 'Report Lost Item' form
        return <ItemReview userRole={userRole} />; 
      case 'analytics':
        return <Analytics userRole={userRole} />;
      case 'audit-logs':
        return <AuditLogs userRole={userRole} />;
      default:
        return <p>Select a tab.</p>;
    }
  };

  // Ensure a simple role check is done on the component level, 
  // though ProtectedRoute handles most of this.
  if (!user || !user.role || !hasPermission(['admin', 'super_admin', 'moderator', 'analyst'])) {
    return <div className="p-6 text-red-500">Access Denied. You do not have permission to view this page.</div>;
  }
  // Find the first accessible tab and set it as active if the current tab is invalid
  // This prevents showing an empty tab if the user doesn't have permissions for the default
  useEffect(() => {
    const accessibleTabs = dashboardTabs.filter(tab => hasPermission(tab.roles));
    if (activeTab === 'user-management' && !hasPermission(['admin', 'super_admin'])) {
      if (accessibleTabs.length > 0) {
        setActiveTab(accessibleTabs[0].id);
      }
    }
  }, [user, activeTab, hasPermission]);


  return (
    <div className="bg-gray-50 min-h-screen p-8">
      <h1 className="text-3xl font-bold text-gray-800 mb-6">Admin Panel</h1>
      
      {/* Tab Navigation */}
      <div className="flex border-b border-gray-200 mb-6">
        {dashboardTabs.map(tab => 
          // Only show tabs the user has permission for
          hasPermission(tab.roles) && (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`py-2 px-4 text-sm font-medium transition-colors duration-200 ${
                activeTab === tab.id
                  ? 'border-b-2 border-indigo-500 text-indigo-600'
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              {tab.name}
            </button>
          )
        )}
      </div>

      {/* Main Content Area */}
      <div className="bg-white p-6 rounded-lg shadow-xl">
        {renderContent()}
      </div>
      
    </div>
  );
};

export default AdminDashboard;
